fn owe(eff:&mut RetainedAllocationEffect<'_>,base:u128,work:u128)->Result<(),ValueError>{let done=eff.performed_work().saturating_sub(base);if done>work{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"fixture recorded more work than it reports"))}let owed=u64::try_from(work-done).map_err(|_|ValueError::literal(ValueRefusalKind::WorkLimit,"fixture work does not fit one original unit"))?;if owed==0||eff.performed(owed)?{Ok(())}else{Err(ValueError::literal(ValueRefusalKind::WorkLimit,"fixture work exceeded its original action"))}}
fn settle_advance(eff:&mut RetainedAllocationEffect<'_>,base:u128,result:Result<RetainedCloneStep,OriginalRetirementFailure>,work:u128)->RetainedWorkOutcome<RetainedCloneStep,OriginalRetirementFailure>{effect::settled(settle_step(eff,base,result,work))}
type Reply<'r>=OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>;
type Done<'r>=OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>;
thread_local!{
 pub(crate) static STALL:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};
 pub(crate) static STALL_INVERSE:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};
 pub(crate) static STALL_PREFLIGHT:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};
 pub(crate) static RECOVERS:std::cell::Cell<usize>=const{std::cell::Cell::new(0)};
}
fn native<T,E>(eff:&mut RetainedAllocationEffect<'_>,work:&mut u128,call:impl for<'r> FnOnce(&mut RetainedAllocationEffect<'_>,OriginalEffectReply<'r,T,E>)->Result<OriginalEffectReplyComplete<'r,T,E>,ValueError>)->Result<Result<T,E>,ValueError>{
 let before=eff.performed_work();let mut stash=None;let done=OriginalEffectReply::borrow(&mut stash).and_then(|reply|call(eff,reply));*work+=eff.performed_work().saturating_sub(before);drop(done?);
 stash.take().ok_or_else(||ValueError::invariant("fixture child left its reply pending"))
}
fn settle_exit(eff:&mut RetainedAllocationEffect<'_>,base:u128,result:Result<RetainedCloneStep,RetirementPollExit>,work:u128)->OriginalRetirementPoll{match result{Ok(step)=>settle_step(eff,base,Ok(step),work),Err(RetirementPollExit::Failed(failure))=>settle_step(eff,base,Err(failure),work),Err(pending@RetirementPollExit::Pending(_))=>match owe(eff,base,work){Ok(())=>RetirementPollExit::finish::<RetainedCloneStep>(Err(pending),work),Err(refusal)=>semio_framework_value::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_work_refusal(refusal)),work})}}}
fn settle_step(eff:&mut RetainedAllocationEffect<'_>,base:u128,result:Result<RetainedCloneStep,OriginalRetirementFailure>,work:u128)->OriginalRetirementPoll{let result=match(result,owe(eff,base,work)){(result,Ok(()))=>result,(Ok(step),Err(refusal))=>Err(OriginalRetirementFailure::from_work_refusal(refusal.with_retained_progress(step.progress()))),(Err(primary),Err(refusal))=>Err(OriginalRetirementFailure::from_owned_parts(None,Some(refusal),None,None,Some(Box::new(primary)),None))};semio_framework_value::RetainedWorkPoll::Complete(RetainedWorkOutcome{result,work})}
