 fn inverse_demand(&self,m:RetainedCloneRef<'_,DocumentMutation>,p:RetainedCloneRef<'_,Document>,_:RetainedCloneRef<'_,Diff>,body:usize,max:u64)->Result<RetirementDemand,ValueError>{Ok(match self.inverse_phase{0=>demand(size_of::<Vec<DocumentMutation>>()+4*size_of::<usize>(),match m.get(){DocumentMutation::RemoveRange{count,..}=>*count,_=>1}.checked_mul(size_of::<DocumentMutation>()).ok_or_else(out_of_range)?),1=>{if !self.fields[self.inverse_field].terminal_is_empty(){return if self.fields[self.inverse_field].close_started(){self.fields[self.inverse_field].close_demand(body)}else{Ok(self.fields[self.inverse_field].begin_close_demand())};}demand(size_of::<RetainedFieldPreparation<String>>()+size_of::<usize>(),0)},2=>return self.field_demand(self.inverse_source(m,p,self.inverse_field),self.inverse_field,body,max),3=>demand(size_of::<DocumentMutation>()*2+2*size_of::<Option<String>>()+size_of::<usize>(),0),_=>demand(size_of::<u8>(),0)})}
 fn inverse_work_demand(&self,m:RetainedCloneRef<'_,DocumentMutation>,p:RetainedCloneRef<'_,Document>,dref:RetainedCloneRef<'_,Diff>,body:usize,max:u64)->Result<u64,ValueError>{self.inverse_demand(m,p,dref,body,max)?;let work=match self.inverse_phase{1=>{let f=&self.fields[self.inverse_field];if f.terminal_is_empty(){1}else if f.close_started(){f.close_work_demand(body)?}else{f.begin_close_work_demand()}},2=>match self.inverse_source(m,p,self.inverse_field){Some(s)=>if self.fields[self.inverse_field].value().is_some(){1}else{self.fields[self.inverse_field].advance_work_demand(s,body,max)?},None=>1},_=>1};Ok(if work<=max{work}else{0})}
