 fn take_inverse(&mut self)->Vec<DocumentMutation>{assert_eq!(self.inverse_phase,4);self.inverse_phase=5;self.inverse.take().unwrap()}
 fn begin_close(&mut self){self.closing=true;}
 fn close_started(&self)->bool{self.closing}
